// src/lib/translations.ts
//
// Central translation map. English is the source of truth.
// German is the first translated locale. Add more locales as needed.
//
// KEY NAMING CONVENTION:
//   section.element — e.g., 'nav.decks', 'profile.signOut'
//   section.element.plural — for plural variants
//
// INTERPOLATION:
//   Use {variableName} for dynamic values — e.g., 'You have {count} credits'
//   The t() function replaces these at runtime.

export type Locale = 'en' | 'de' | 'fr';

// Map from base_language profile values to locale codes.
// Korean intentionally maps to 'en' — Korean users see the English UI
// because we don't ship a Korean translation of the app interface.
export const LANGUAGE_TO_LOCALE: Record<string, Locale> = {
  English: 'en',
  German: 'de',
  French: 'fr',
  Korean: 'en',
  Spanish: 'en',
};

const warnedFallbackKeys = new Set<string>();

function warnMissingLocaleKey(locale: Locale, key: string) {
  if (locale === 'en' || !import.meta.env?.DEV) return;

  const warningKey = `${locale}:${key}`;
  if (warnedFallbackKeys.has(warningKey)) return;

  warnedFallbackKeys.add(warningKey);
  console.warn('[i18n] Missing locale key; falling back to English', { locale, key });
}

// Shared translation function builder — used by useTranslation and useLandingLocale
export function createT(locale: Locale) {
  return (key: string, vars?: Record<string, string | number>): string => {
    const localeString = translations[locale]?.[key];
    const englishString = translations.en?.[key];

    if (localeString === undefined && englishString !== undefined) {
      warnMissingLocaleKey(locale, key);
    }

    let str = localeString ?? englishString ?? key;
    if (vars) {
      for (const [varName, value] of Object.entries(vars)) {
        str = str.replace(new RegExp(`\\{${varName}\\}`, 'g'), String(value));
      }
    }
    return str;
  };
}

export type TranslationFn = ReturnType<typeof createT>;

export type SpeakApiErrorPayload = {
  error?: unknown;
  detail?: unknown;
  code?: unknown;
  retry_after_seconds?: unknown;
};

function getErrorText(value: unknown): string | null {
  return typeof value === 'string' && value.trim().length > 0 ? value.trim() : null;
}

function getRetryAfterSeconds(value: unknown): number | null {
  const seconds = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(seconds) && seconds > 0 ? seconds : null;
}

function isSpeakLimitError(status: number, payload: SpeakApiErrorPayload | null): boolean {
  if (status === 429) return true;
  const text = `${getErrorText(payload?.error) ?? ''} ${getErrorText(payload?.detail) ?? ''}`.toLowerCase();
  return text.includes('quota') || text.includes('rate') || text.includes('limit') || text.includes('too many');
}

export function formatSpeakRetryAfter(t: TranslationFn, retryAfterSeconds: unknown): string | null {
  const seconds = getRetryAfterSeconds(retryAfterSeconds);
  if (seconds === null) return null;

  if (seconds < 60) {
    const count = Math.max(1, Math.ceil(seconds));
    return t(count === 1 ? 'speak.retryAfter.second' : 'speak.retryAfter.seconds', { count });
  }

  if (seconds < 3600) {
    const count = Math.max(1, Math.ceil(seconds / 60));
    return t(count === 1 ? 'speak.retryAfter.minute' : 'speak.retryAfter.minutes', { count });
  }

  const count = Math.max(1, Math.ceil(seconds / 3600));
  return t(count === 1 ? 'speak.retryAfter.hour' : 'speak.retryAfter.hours', { count });
}

export function formatSpeakApiError(
  t: TranslationFn,
  status: number,
  payload: SpeakApiErrorPayload | null,
  fallbackKey = 'speak.error.requestFailed',
): string {
  const code = getErrorText(payload?.code);
  if (code === 'speak_trial_exhausted') return t('speak.trialExhausted');
  if (code === 'speak_allowance_exhausted') return t('speak.allowanceExhausted');
  if (code === 'premium_required') return t('speak.livePremiumRequired');
  if (code === 'live_allowance_exhausted') return t('speak.liveAllowanceExhausted');
  if (code === 'live_mint_in_progress') return t('speak.livePreparing');
  if (code === 'live_reservation_expired') return t('speak.liveExpired');
  if (code === 'live_reconnect_limit') return t('speak.liveReconnectLimit');
  if (code === 'request_timeout') return t('speak.error.requestTimedOut');

  if (isSpeakLimitError(status, payload)) {
    const retryAfter = formatSpeakRetryAfter(t, payload?.retry_after_seconds);
    return retryAfter
      ? t('speak.limitReachedRetry', { time: retryAfter })
      : t('speak.limitReached');
  }

  return getErrorText(payload?.detail) ?? getErrorText(payload?.error) ?? t(fallbackKey);
}

